                        ecL->VpiName(std::string(nv.symbol.name));
                        ecL->VpiDecompile(decL);
                        ecL->VpiValue(valL);
                        ecL->VpiSize(typedL
                                         ? (int32_t)psym.getType().getBitWidth()
                                         : 64);
                        ecL->VpiParent(ref);
                        ref->Actual_group(ecL);
