                                    case 'b':
                                        c->VpiValue("BIN:" + dg8);
                                        c->VpiConstType(vpiBinaryConst);
                                        break;
                                    case 'h':
                                        c->VpiValue("HEX:" + dg8);
                                        c->VpiConstType(vpiHexConst);
                                        break;
                                    case 'o':
                                        c->VpiValue("OCT:" + dg8);
                                        c->VpiConstType(vpiOctConst);
                                        break;
                                    case 'd':
