                        // component (r10rgg14's rule, verifier fix included).
                        const HierarchicalValueExpression* hve17 =
                            bb->kind == ExpressionKind::HierarchicalValue
                                ? &bb->as<HierarchicalValueExpression>()
                                : nullptr;
