                                auto* bsv = s.MakeBit_select();
                                bsv->VpiName(bn);
                                bsv->VpiFullName(cn);
                                bsv->VpiParent(hp);
                                setLoc(bsv, SourceRange(exprStart + co,
                                                        exprStart + co + bn.size()));
