                        rc7->VpiSize(rw7);
                        rc7->VpiValue("BIN:" + rbits7);
                        rc7->VpiConstType(vpiBinaryConst);
                        auto* rrt7 = s.MakeRef_typespec();
                        rrt7->VpiParent(rc7);
                        rrt7->VpiFullName("");
                        rrt7->Actual_typespec(s.MakeInt_typespec());
                        rc7->Typespec(rrt7);
