                            sfc9->VpiLineNo(0);
                            sfc9->VpiColumnNo(0);
                            sfc9->VpiEndLineNo(0);
                            sfc9->VpiEndColumnNo(0);
                            e = (*sfc9->Tf_call_args())[0];
